 "content": "def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    anchors = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 5]
    def neighborhood_count(p):
        r, c = p
        return sum(1 for rr in range(max(0, r-3), min(h, r+4))
                   for cc in range(max(0, c-3), min(w, c+4))
                   if (rr, cc) != p and grid[rr][cc] != 0)
    source = max(anchors, key=neighborhood_count)
    target = min((p for p in anchors if p != source), key=neighborhood_count)
    sr, sc = source
    tr, tc = target
    dr, dc = tr-sr, tc-sc
    for r in range(h):
        for c in range(w):
            if (r, c) == source or grid[r][c] == 0:
                continue
            rr, cc = r+dr, c+dc
            if 0 <= rr < h and 0 <= cc < w:
                out[rr][cc] = grid[r][c]
    out[tr][tc] = 0
    return out
